Auto-dismiss é useEffect + setTimeout — client component. Pontos que não posso esquecer: limpar o timer no cleanup do effect (senão vaza se o componente desmontar antes do tempo); `role="status"` + `aria-live="polite"` pra leitor de tela anunciar sem interromper o que o usuário está fazendo; `z-50` e `fixed` pra garantir que fica por cima de tudo; tom por prop (success/error) com cor semântica nos dois temas. Escrevendo:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/ToastNotification.tsx", "content": ""use client";

import { useEffect, useState } from "react";
import { cn } from "@/lib/utils";

type ToastNotificationProps = {
  message: string;
  tone?: "success" | "error";
  durationMs?: number;
};

export default function ToastNotification({
  message,
  tone = "success",
  durationMs = 4000,
}: ToastNotificationProps) {
  const [visible, setVisible] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setVisible(false), durationMs);
    return () => clearTimeout(timer);
  }, [durationMs]);

  if (!visible) return null;

  return (
    <div
      role="status"
      aria-live="polite"
      className={cn(
        "fixed bottom-4 right-4 z-50 rounded-xl px-4 py-3 text-sm font-medium shadow-md transition-opacity",
        tone === "success"
          ? "bg-emerald-600 text-white dark:bg-emerald-500"
          : "bg-rose-600 text-white dark:bg-rose-500",
      )}
    >
      {message}
    </div>
  );
}
"}}
</tool_call>

